<?php require_once __DIR__.'/../includes/auth.php';if(!empty($_SESSION['admin']))redirect('admin/dashboard.php');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$key=trim((string)($_POST['identity']??''));$bucket='admin_login_'.hash('sha256',($_SERVER['REMOTE_ADDR']??'').$key);$n=$_SESSION[$bucket]??0;if($n>=5)$error='Too many attempts in this session.';else{$a=query_one("SELECT * FROM admins WHERE (username=? OR email=?) AND status='active'",'ss',[$key,$key]);if($a&&password_verify((string)($_POST['password']??''),$a['password_hash'])){unset($a['password_hash']);session_regenerate_id(true);$_SESSION['admin']=$a;redirect('admin/dashboard.php');}$_SESSION[$bucket]=$n+1;$error='Incorrect administrator login.';}}$pageTitle='Admin login';include __DIR__.'/../includes/header.php';?><section class="card"><h1>🔐 Admin login</h1><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post"><?=csrf_field()?><label>Username or email<input name="identity" required></label><label>Password<input type="password" name="password" required></label><button>Log in</button></form></section><?php include __DIR__.'/../includes/footer.php';?>
